      expv[60] = 129'h1ad53cf97dfd187918912c9a3cbe66143;
      expv[61] = 129'h1ad53cf97dfd187918912c9a3cbe66143;
      expv[62] = 129'h129af6e9677e3d50687c05051bc080107;
      expv[63] = 129'h129af6e9677e3d50687c05051bc080107;
      mismatches = 0;
      shown = 0;
      for (c = 0; c < N; c = c + 1) begin
        bad = 0;
        for (b = 0; b < OW; b = b + 1)
          if (expv[c][b] !== 1'bx && act[c][b] !== expv[c][b]) bad = 1;
        if (bad) begin
          mismatches = mismatches + 1;
          if (shown < 10) begin
            $display("MISMATCH cycle %0d: inputs=%h expected=%h got=%h", c, stim[c], expv[c], act[c]);
            shown = shown + 1;
          end
        end
      end
      if (mismatches == 0) $display("PASS %0d/%0d cycles", N, N);
      else $display("FAIL %0d/%0d cycles mismatched", mismatches, N);
    end
    $finish;
  end
